def chain_follow(chain):
    chain_dict = {}
    for token in chain:
        chain_dict[token] = chain.index(token)

    current = chain_dict['c']
    result = []

    while current:
        result.append(current)
        next_token = chain_dict[current]
        current = next_token

    return ','.join(result)
